"""Build crawlable static HTML and explicitly selected public assets."""
from pathlib import Path
import json, html, shutil, re, hashlib
from assets import build_assets, ROOT, DEST

OUT=DEST.parent; OUT.mkdir(parents=True,exist_ok=True)
cfg=json.loads((ROOT/'config/site.json').read_text())
photos=build_assets(); byid={p['id']:p for p in photos}
e=lambda x:html.escape(str(x),quote=True)
DOMAIN='https://sdatarneit.au'
PUBLIC_EMAIL='enquiries@sdatarneit.au'
NDIS='https://ndis.gov.au/participants/home-and-living/types-home-and-living-supports/what-specialist-disability-accommodation-sda'
PHONE=cfg['publicPhone']; PHONE_HREF=cfg['publicPhoneHref']; SMS_HREF=cfg['publicSmsHref']

def img(slug,alt,cls='',eager=False,plan=False):
    widths=[400,1000,2000] if plan else [240,800,1600]
    from PIL import Image
    with Image.open(DEST/f'{slug}-{widths[1]}.webp') as source: width,height=source.size
    return f'<img class="{cls}" src="/assets/{slug}-{widths[1]}.webp" srcset="'+', '.join(f'/assets/{slug}-{w}.webp {w}w' for w in widths)+f'" sizes="(max-width: 700px) 100vw, 70vw" alt="{e(alt)}" width="{width}" height="{height}" '+('fetchpriority="high" loading="eager"' if eager else 'loading="lazy"')+' decoding="async">'
def photo(n,cls='',eager=False):return img(byid[n]['slug'],byid[n]['caption'],cls,eager)
def link(url,txt,cls='text-link'):return f'<a class="{cls}" href="{url}">{txt}<span aria-hidden="true"> ↗</span></a>'
def section_title(kicker,title,desc=''):return f'<div class="section-heading"><p class="eyebrow">{kicker}</p><h2>{title}</h2>'+ (f'<p>{desc}</p>' if desc else '')+'</div>'
def faq(q,a):return f'<details class="faq"><summary>{q}</summary><div>{a}</div></details>'
def cta():return f'<section class="cta-band"><div><p class="eyebrow">YOUR NEXT STEP</p><h2>Let’s talk about the home.</h2><p>Ask about availability or arrange an inspection. Your enquiry goes directly to Al, the owner of the home.</p></div><div class="cta-actions"><a class="button light" href="{PHONE_HREF}">Call Al · {PHONE}</a><a class="button outline-light" href="{SMS_HREF}">Send a text</a><a class="cta-form-link" href="/enquiries/">Send an enquiry ↗</a></div></section>'

nav='<a href="/">Overview</a><a href="/the-home/">The home</a><a href="/living-in-tarneit/">Life in Tarneit</a><a href="/sda-and-support/">SDA &amp; support</a>'
def page(path,title,description,body):
    canonical=DOMAIN+path
    currentnav=nav.replace(f'href="{path}"',f'href="{path}" aria-current="page"')
    schema={'@context':'https://schema.org','@type':'WebSite','name':'SDA Tarneit','url':DOMAIN} if path=='/' else {'@context':'https://schema.org','@type':'WebPage','name':title,'url':canonical}
    doc=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#173c33"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><meta property="og:image" content="{DOMAIN}/assets/photo-051-1600.webp"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><script defer src="/app.js"></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a href="/" class="brand" aria-label="SDA Tarneit home"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M5 20 20 7l15 13M10 17v18h20V17M17 35V23h7v12"/></svg><span>SDA<span class="brand-place">TARNEIT</span></span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">{currentnav}</nav><a class="header-phone" href="{PHONE_HREF}">Call Al <strong>{PHONE}</strong></a><a class="button header-enquire" href="/enquiries/">Enquire <span aria-hidden="true">↗</span></a></div></header><main id="main">{body}</main><footer><div class="footer-top"><a class="footer-brand" href="/">SDA TARNEIT<span>One home. A considered next step.</span></a><div><p>Social Street, Tarneit VIC 3029<br>Wyndham · Melbourne’s western suburbs</p><p><a class="footer-contact" href="{PHONE_HREF}">Call Al about this home<br>{PHONE}</a> · <a href="{SMS_HREF}">Text</a></p><p><!--email_off--><a href="mailto:{PUBLIC_EMAIL}">Email us: {PUBLIC_EMAIL}</a><!--/email_off--></p></div><div><a href="/enquiries/">Enquiries &amp; inspections</a><a href="/privacy/">Privacy</a><a href="/sda-and-support/">Frequently asked questions</a><a href="/sda-and-support/#support-professionals">For support teams</a></div></div><div class="footer-bottom"><p>High Physical Support SDA accommodation on Social Street, Tarneit. Ask about availability or arrange an inspection.</p><span>© 2026 SDA Tarneit</span></div></footer><dialog id="media-dialog" aria-labelledby="media-title"><div class="dialog-top"><div><h2 id="media-title">Property photos</h2><p id="media-note"></p></div><button id="close-dialog" class="icon-button" aria-label="Close media viewer">✕</button></div><div id="media-content"></div><div id="dialog-navigation"><button class="icon-button" id="dialog-prev" aria-label="Previous photo">←</button><p id="dialog-counter" aria-live="polite"></p><button class="icon-button" id="dialog-next" aria-label="Next photo">→</button></div><div id="dialog-thumbnails" aria-label="Choose a photo"></div></dialog></body></html>'''
    for asset in ['styles.css','app.js']:
        version=hashlib.sha256((ROOT/'src'/asset).read_bytes()).hexdigest()[:12]
        doc=doc.replace(f'"/{asset}"',f'"/{asset}?v={version}"')
    folder=OUT/path.strip('/');folder.mkdir(parents=True,exist_ok=True);(folder/'index.html').write_text(doc,encoding='utf-8')

hero_index=photos.index(byid[51])
thumbs=''.join(f'<a href="/assets/{p["slug"]}-1600.webp" class="photo-thumb" data-photo="{i}" aria-label="Photo {i+1}: {e(p["caption"])}"><img src="/assets/{p["slug"]}-240.webp" alt="{e(p["caption"])}" width="240" height="135" loading="lazy"><span>{i+1:02}</span></a>' for i,p in enumerate(photos))
quick=''.join(f'<a href="/assets/{byid[n]["slug"]}-1600.webp" data-main-photo="{photos.index(byid[n])}" aria-label="Show {e(byid[n]["caption"])}"><img src="/assets/{byid[n]["slug"]}-240.webp" width="240" height="135" alt="{e(byid[n]["caption"])}" loading="lazy"></a>' for n in [51,8,29,80,97,108])
gallery=f'''<section class="property-media" aria-label="Explore the property"><div class="media-grid"><div class="main-photo"><a id="main-photo-link" href="/assets/photo-051-1600.webp" data-photo="{hero_index}" aria-label="Enlarge property photo">{photo(51,'hero-image',True)}</a><span class="photo-label">THE ACTUAL HOME</span><div class="main-photo-controls"><button id="main-prev" class="icon-button" aria-label="Previous property photo">←</button><span id="main-counter" aria-live="polite">{hero_index+1} / {len(photos)}</span><button id="main-next" class="icon-button" aria-label="Next property photo">→</button></div></div><div class="media-options"><a class="media-tile" href="#all-photos" data-photo="0">{photo(8)}<span><b>Browse photos</b><small>{len(photos)} property &amp; neighbourhood photos <i aria-hidden="true">↗</i></small></span></a><a class="media-tile" href="/walkthrough/" data-video>{photo(75)}<span><b><i aria-hidden="true">▷</i> Watch walkthrough</b><small>2 min 15 sec <i aria-hidden="true">↗</i></small></span></a><a class="floorplan-tile" href="/the-home/#floorplans"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M5 5h30v30H5zM5 17h14V5M19 17v18M19 26h16M27 5v12h8"/></svg><span><b>View floorplan</b><small>Understand the layout</small></span><i aria-hidden="true">↗</i></a></div></div><div class="quick-thumbs" aria-label="Property photo previews">{quick}<a class="all-photos-button" href="#all-photos">All {len(photos)} photos →</a></div><p class="media-disclaimer">Every photo of the home on this site is a real photo of the property. The floor plan is an illustrative marketing plan; furniture shown does not confirm rental inclusions.</p><details id="all-photos" class="photo-collection"><summary>Explore all {len(photos)} photos</summary><div class="thumbnail-grid">{thumbs}</div></details></section>'''

home=f'''<div class="wrap"><section class="intro"><p class="eyebrow">SOCIAL STREET · TARNEIT · WYNDHAM</p><h1>SDA accommodation in Tarneit:<br><em>two participant vacancies available.</em></h1><p class="intro-copy">Two vacant participant bedrooms are available in this High Physical Support Specialist Disability Accommodation home in Tarneit, Wyndham, in Melbourne’s western suburbs. Each bedroom has an ensuite, and a separate overnight onsite assistance (OOA) room is provided for support staff.</p><div class="intro-contact"><a class="button" href="{PHONE_HREF}">Call Al about this home <strong>{PHONE}</strong></a><a class="intro-sms" href="{SMS_HREF}">Or send a text</a></div><div class="top-facts" aria-label="Key home facts"><div><strong>High Physical Support</strong><span>SDA design category</span></div><div><strong>2 vacancies</strong><span>participant bedrooms, each with an ensuite</span></div><div><strong>Roll-in showers</strong><span>in the participant ensuites</span></div><div><strong>1 OOA room</strong><span>for overnight support staff</span></div></div></section><section class="funding-invitation"><h2>Have a different funding or household arrangement?</h2><p>This home is a High Physical Support SDA home. Al is happy to discuss whether Improved Liveability, Fully Accessible or a different funded household size may be considered.</p><a class="text-link" href="/sda-and-support/#funding-options">Talk through funding and household options ↗</a></section>{gallery}<section class="home-attributes section-space"><p class="eyebrow">THE HOME, PRACTICALLY</p><h2>Room for your routines and your choices.</h2><div class="three-cards"><article><span class="card-number">01 / BEDROOMS</span><h3>Two participant vacancies</h3><p>Both participant bedrooms are vacant and have ensuites with roll-in showers. Bedroom one is furnished and ready; bedroom two is unfurnished. The OOA room is unfurnished and is for overnight support staff, not a third participant.</p></article><article><span class="card-number">02 / ACCESS &amp; FEATURES</span><h3>Designed around access</h3><p>Home features include step-free access, wider doorways and hallways, accessible bathrooms and kitchen, a height-adjustable bench, back-up battery, video intercom and provision for a future hoist. Heating and cooling, dishwasher, study, solar panels, alarm and remote garage are also listed.</p><p>The home is fully fenced, with a double garage, covered alfresco and rear garden.</p></article><article><span class="card-number">03 / LIVING ARRANGEMENTS</span><h3>Bring your own supports</h3><p>Residents can bring their own support provider and have a say in any onsite shared-supports provider. Pets are welcome.</p><p>Available as Medium Term Accommodation (MTA) or an ongoing lease. MTA funding is available only in specific circumstances; <a href="https://www.ndis.gov.au/participants/home-and-living/types-home-and-living-supports/what-medium-term-accommodation-mta">check the NDIS MTA guidance</a> and talk with your NDIS contact.</p></article></div></section><section class="split section-space"><div>{section_title('A HOME FOR YOUR HOUSEHOLD','A place to feel at home.')}<p>This home may suit someone living independently, with family, or sharing with a partner or spouse. Talk with Al about what you have in mind.</p><p>Explore the rooms, features and location, then tell us what matters most to you.</p>{link('/the-home/','Explore the home & accessibility')}</div><figure class="editorial-image">{photo(29)}<figcaption>Participant bedroom one · furnished</figcaption></figure></section><section class="feature-links section-space"><div>{section_title('FOR SUPPORT TEAMS','A clear starting point for a property conversation.')}<p>Support coordinators, supported independent living (SIL) providers and allied health professionals can review the configuration, floor plan and access features, then discuss an individual household match with Al.</p>{link('/sda-and-support/#support-professionals','Information for support professionals')}</div></section>{cta()}</div>'''
page('/','SDA Tarneit | 2 vacancies, High Physical Support home','Two vacant participant bedrooms in a High Physical Support SDA home in Tarneit, Wyndham. Call 0480 027 263.',home)

plans=f'''<section id="floorplans" class="section-space">{section_title('UNDERSTAND THE LAYOUT','Two different views. One actual home.','Use the 2D plan to understand the layout. Use the 3D concept only to imagine how furnished spaces might look.')}<div class="plan-grid"><article><a href="/assets/tarneit-floor-plan.svg" data-plan="2d">{img('plan-2d','2D floor plan showing two participant bedrooms, OOA room, three shower bathrooms and the site layout',plan=True)}</a><p class="eyebrow">LAYOUT REFERENCE</p><h3>2D floor plan</h3><p>An illustrative 2D marketing floorplan showing the rooms and outdoor layout. Use it to explore the home, then check dimensions during an inspection. It is not a construction drawing.</p><div class="link-row">{link('/assets/tarneit-floor-plan.pdf','Download PDF')}{link('/assets/tarneit-floor-plan.svg','Open full-size plan')}</div></article><article><a href="/assets/plan-3d-2000.webp" data-plan="3d">{img('plan-3d','Illustrative furnished 3D concept of the home, not a photograph or authoritative floorplan',plan=True)}</a><p class="eyebrow">ILLUSTRATIVE FURNISHED CONCEPT</p><h3>3D concept view</h3><p>An illustrative furnished 3D concept to help you picture the spaces. It is not a photograph; furniture and fittings may differ from the actual home.</p><p>Furniture pictured does not establish what is included.</p>{link('/assets/plan-3d-2000.webp','Open concept image')}</article></div></section>'''
features=f'''<div class="wrap"><section class="page-intro"><p class="eyebrow">THE SOCIAL STREET HOME · TARNEIT</p><h1>High Physical Support SDA home in Tarneit.</h1><p>Two vacant participant bedrooms with ensuites and roll-in showers, plus a separate overnight onsite assistance (OOA) room for support staff.</p></section><div class="wide-image">{photo(72,'',True)}</div><p class="media-disclaimer">Every photo of the home on this site is a real photo of the property. The floor plan is an illustrative marketing plan.</p><section class="section-space two-columns"><div><h2>Bedrooms and bathrooms</h2><p>Both participant bedrooms are vacant. Bedroom one is furnished and ready; bedroom two is unfurnished. Each has an ensuite with a roll-in shower.</p><p>The separate OOA room is unfurnished and is for overnight support staff, not a participant bedroom. There are three shower bathrooms in total.</p></div><div><h2>Shared living and outdoors</h2><p>The home has shared kitchen, dining and living areas, a covered alfresco, rear garden, study and fully fenced yard. Pets are welcome.</p><p>There is a double garage with remote access, heating and cooling, a dishwasher, solar panels, an alarm and video intercom.</p></div></section><section id="accessibility" class="tinted section-space"><h2>Access and home features</h2><p>Home features include step-free access, wider doorways and hallways, accessible bathrooms and kitchen, a height-adjustable bench and back-up battery. The structure supports a future hoist.</p><p>The design category is High Physical Support. An inspection is the best way to discuss your individual access and equipment needs with Al.</p></section>{plans}<section class="section-space"><h2>Household and support arrangements</h2><p>The home may suit someone living independently, with family, or sharing with a partner or spouse. Residents can bring their own support provider and have a say in any onsite shared-supports provider. Al is happy to discuss your preferred arrangement.</p><p>The home is available for Medium Term Accommodation or an ongoing lease. MTA funding is available only in specific circumstances; check with your NDIS contact.</p><p><a href="{PHONE_HREF}">Call Al on {PHONE}</a> or <a href="{SMS_HREF}">send a text</a> to discuss the home or arrange an inspection.</p></section>{cta()}</div>'''
page('/the-home/','The Tarneit SDA home | 2 vacancies & access features','See two vacant High Physical Support SDA bedrooms with ensuites and roll-in showers, OOA room, home features and the illustrative floor plan.',features)

location=f'''<div class="wrap"><section class="page-intro"><p class="eyebrow">TARNEIT · WYNDHAM · MELBOURNE’S WEST</p><h1>Everyday life in Tarneit.</h1><p>Get to know the surroundings and check the services and routes that matter in your day-to-day life.</p></section><section class="location-grid"><article>{img('nearby-playground','Aerial photograph of the local playground and surrounding paths',eager=True)}<div><p class="eyebrow">TIME OUTDOORS</p><h2>Local playground &amp; open space</h2><p>The local park and playground are around 50 metres from the house. Explore the paths and open space when you visit; an inspection is a chance to assess access for yourself.</p></div></article><article>{img('nearby-shopping','Aerial photograph of Tarneit Central shopping centre')}<div><p class="eyebrow">EVERYDAY AMENITIES</p><h2>Tarneit Central</h2><p>Tarneit Central is a local shopping destination. Check its current stores and services when planning a visit.</p><a href="https://tarneitcentral.com.au/" rel="noopener">Tarneit Central website ↗</a></div></article></section><section class="section-space two-columns"><article><h2>Transport</h2><p>Tarneit Station connects the area with V/Line trains and local buses. Check current services, station information and access before you travel.</p><a href="https://transport.vic.gov.au/stop/32364/tarneit-station/2/bus" rel="noopener">Transport Victoria: Tarneit Station ↗</a></article><article><h2>Library and community</h2><p>Julia Gillard Library Tarneit is at 150 Sunset Views Boulevard. Check Wyndham City for current opening hours and facilities.</p><a href="https://www.wyndham.vic.gov.au/venues/julia-gillard-library-tarneit" rel="noopener">Wyndham City: Julia Gillard Library ↗</a></article><article><h2>Hospital services</h2><p>Werribee Mercy Hospital is a hospital serving the local community. Check Mercy Health for current services and visitor information.</p><a href="https://health-services.mercyhealth.com.au/our-health-services/werribee-mercy-hospital/" rel="noopener">Mercy Health: Werribee Mercy Hospital ↗</a></article><article><h2>Considering SDA in Wyndham?</h2><p>This property is in Tarneit, within Wyndham. If your search includes nearby suburbs, you are welcome to consider whether Tarneit suits your plans. This site features one home, on Social Street in Tarneit.</p><p>Ask about the two vacant participant bedrooms, the home’s features or an inspection.</p><a href="/the-home/">Explore the home ↗</a></article></section><aside class="note">Service information can change. Confirm current opening hours, routes, facilities and access details with each provider before travelling.</aside>{cta()}</div>'''
page('/living-in-tarneit/','Tarneit and Wyndham | local guide & SDA vacancies','Explore Tarneit: the local park about 50 m away, shopping, public transport, library and health services near this SDA home.',location)

support=f'''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">YOUR QUESTIONS ABOUT THE HOME</p><h1>Questions about the home?<br>Talk with Al.</h1><p>Two participant vacancies in a High Physical Support home in Tarneit. Participants, families, support coordinators and providers are welcome to call Al and discuss the details.</p><p><a class="button" href="{PHONE_HREF}">Call Al · {PHONE}</a> <a class="button" href="{SMS_HREF}">Send a text</a></p></section><section id="funding-options" class="tinted"><p class="eyebrow">FUNDING &amp; HOUSEHOLD OPTIONS</p><h2>Let’s talk through what you’re looking for.</h2><p>This home is a High Physical Support SDA home with two vacant participant bedrooms, each with an ensuite and roll-in shower, plus a separate overnight onsite assistance (OOA) room for support staff. Al is happy to discuss whether Improved Liveability, Fully Accessible or a different funded household size may be considered.</p></section><section class="section-space"><h2>Frequently asked questions</h2>{faq('How many participant vacancies are available?','<p>There are two vacant participant bedrooms. There are no residents currently in the home.</p>')}{faq('What is the room configuration?','<p>There are two participant bedrooms, each with an ensuite and roll-in shower, plus a separate unfurnished overnight onsite assistance (OOA) room for support staff. The OOA room is not a third participant bedroom. There are three shower bathrooms in total.</p>')}{faq('What does High Physical Support mean?','<p>High Physical Support is an SDA design category for housing with a high level of physical access features for people who need very high levels of support. It does not determine whether a specific person or household is a match. <a href="{NDIS}">Read the NDIS SDA overview</a>.</p>')}{faq('Could another funding category or household size be discussed?','<p>This home is a High Physical Support SDA home. Al is happy to discuss whether Improved Liveability, Fully Accessible or a different funded household size may be considered.</p>')}{faq('Can residents choose their own support provider?','<p>Residents can bring their own support provider and have a say in any onsite shared-supports provider. Discuss the support arrangements with Al.</p>')}{faq('What is furnished?','<p>Participant bedroom one is furnished and ready. Participant bedroom two and the OOA room are unfurnished. Ask Al about any other rental inclusions.</p>')}{faq('Are pets welcome?','<p>Yes, pets are welcome.</p>')}{faq('Is this available for MTA or an ongoing lease?','<p>The home is available for Medium Term Accommodation (MTA) or an ongoing lease. MTA funding is available only in specific circumstances; <a href="https://www.ndis.gov.au/participants/home-and-living/types-home-and-living-supports/what-medium-term-accommodation-mta">check the NDIS MTA guidance</a> and talk with your NDIS contact.</p>')}{faq('Can I inspect the home?','<p>Yes. Call or text Al to discuss the vacancies and arrange an inspection.</p>')}{faq('How do I start?','<p>Call <a href="{PHONE_HREF}">{PHONE}</a>, <a href="{SMS_HREF}">send a text</a>, or use the <a href="/enquiries/">enquiry form</a>. You can start with a question about the home or your preferred arrangement.</p>')}</section><section id="support-professionals" class="section-space"><p class="eyebrow">FOR SUPPORT TEAMS</p><h2>Information for support coordinators, SIL providers and allied health professionals</h2><p>Use these details to start an individual property discussion: two vacant participant bedrooms with ensuites and roll-in showers, and a separate OOA room for overnight support staff. Residents can bring their own support provider and have a say in any onsite shared-supports provider.</p><p>Review the <a href="/the-home/#floorplans">illustrative floor plan and home features</a>, the <a href="/#all-photos">real property photos</a>, the <a href="/walkthrough/">walkthrough and room-by-room guide</a>, and the <a href="/living-in-tarneit/">Tarneit location information</a>. Call or text Al with questions or to arrange an inspection.</p></section>{cta()}</div>'''.replace('{NDIS}',NDIS).replace('{PHONE_HREF}',PHONE_HREF).replace('{SMS_HREF}',SMS_HREF).replace('{PHONE}',PHONE)
page('/sda-and-support/','SDA support and vacancies | Tarneit FAQs','Two vacant High Physical Support SDA bedrooms in Tarneit. Read clear answers about vacancies, features, funding conversations, support and inspections.',support)

enquiries='''<div class="wrap"><section class="page-intro"><p class="eyebrow">ENQUIRIES &amp; INSPECTIONS</p><h1>Let’s start with your questions.</h1><p><strong>Two participant vacancies:</strong> in a High Physical Support SDA home in Tarneit, with ensuites and a separate overnight assistance room.</p><p><a class="button" href="{PHONE_HREF}">Call Al · {PHONE}</a> <a class="button" href="{SMS_HREF}">Send a text</a></p></section><div class="enquiry-layout"><section class="enquiry-context"><h2>Ask about availability or arrange an inspection.</h2><p>Prefer to talk? <a href="{PHONE_HREF}">Call Al on {PHONE}</a> or <a href="{SMS_HREF}">send a text</a>.</p><p>Your enquiry goes directly to Al, the owner of the Social Street home. Al can answer your questions and arrange an inspection.</p><p>Choose the form, or email us directly at <!--email_off--><a href="mailto:{PUBLIC_EMAIL}">{PUBLIC_EMAIL}</a><!--/email_off-->.</p><ol class="steps"><li><strong>Tell us what you’re looking for</strong><span>Ask a question about the home, the available rooms or an inspection.</span></li><li><strong>Hear from Al</strong><span>Al will use the contact details you provide to respond.</span></li><li><strong>Explore the next step</strong><span>Arrange a closer look and discuss individual suitability with Al.</span></li></ol><p>Participants, families, support coordinators and SIL providers are all welcome. You are welcome to get in touch while you are still exploring your options.</p></section><section class="form-panel"><h2>Send an enquiry</h2><p id="form-availability">A few details are enough to start a conversation.</p><form id="enquiry-form" action="/api/enquiries" method="post"><fieldset id="enquiry-fields" disabled><legend class="sr-only">Your enquiry details</legend><div class="field-row"><label>Your name <span>(required)</span><input name="name" autocomplete="name" required maxlength="100"></label><label>Email <span>(required)</span><input type="email" name="email" autocomplete="email" required maxlength="254"></label></div><div class="field-row"><label>Phone <span>(optional)</span><input type="tel" name="phone" autocomplete="tel" maxlength="40"></label><label>I am enquiring as<select name="role"><option>A participant</option><option>A family member</option><option>A support coordinator</option><option>A SIL provider</option><option>Someone else</option></select></label></div><label>I’d like to ask about<select name="topic"><option>The home and suitability</option><option>Current availability</option><option>Arranging an inspection</option><option>Something else</option></select></label><label>Your questions <span>(required)</span><textarea name="message" rows="5" required minlength="10" maxlength="4000" aria-describedby="message-help"></textarea></label><p id="message-help" class="field-help">Please do not send medical documents, NDIS numbers or other sensitive records. If you are enquiring for someone else, share only what they are comfortable with.</p><div class="honeypot" aria-hidden="true"><label>Leave this blank<input name="website" tabindex="-1" autocomplete="off" maxlength="100"></label></div><label class="checkbox"><input type="checkbox" name="consent" required><span>I agree to be contacted about my enquiry and have read the <a href="/privacy/">privacy information</a>.</span></label><button type="submit" class="button">Send enquiry</button></fieldset><noscript><p>Please enable JavaScript to use this enquiry form. The form cannot send while JavaScript is disabled.</p></noscript><p id="form-result" role="status" aria-live="polite" tabindex="-1"></p></form></section></div></div>'''.replace('{PUBLIC_EMAIL}',PUBLIC_EMAIL).replace('{PHONE_HREF}',PHONE_HREF).replace('{SMS_HREF}',SMS_HREF).replace('{PHONE}',PHONE)
page('/enquiries/','Enquiries & inspections | SDA Tarneit','Ask about two vacant participant bedrooms in a High Physical Support SDA home in Tarneit, or call Al on 0480 027 263.',enquiries)

privacy='''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">YOUR INFORMATION</p><h1>Privacy &amp; enquiries</h1><p>Share just enough to start a conversation about the home.</p></section><section class="section-space prose"><h2>What we collect</h2><p>The enquiry form collects your name, email address, optional phone number, who you are enquiring as, enquiry purpose and message, together with your consent to be contacted. We add a submission time and unique enquiry reference. If you email us directly, we receive the sender address and the message and attachments you choose to include.</p><p>Please do not submit medical documents, NDIS participant numbers, financial documents or other sensitive records. If you are enquiring for someone else, share only information they are comfortable with you providing.</p><h2>How enquiries are stored and used</h2><p>Form submissions are sent over an encrypted connection and saved as private files on the website’s server for the owner to review. These files are outside the public website and cannot be accessed through a website link. They are not stored in your browser or published online.</p><p>The website emails form details through Resend, our email delivery provider, to the owner’s Gmail. The notification includes your name, contact details, enquiry purpose, message, submission time and reference, with a JSON copy attached. Resend processes the message to deliver it, and Google receives it in the owner’s mailbox. If email delivery is delayed or fails, the enquiry remains saved on the website’s server.</p><p>If you call or text the public number, the information you choose to share goes to the owner so they can reply; calls and texts are handled outside this website.</p><p>Messages sent directly to <!--email_off--><a href="mailto:{PUBLIC_EMAIL}">{PUBLIC_EMAIL}</a><!--/email_off--> are forwarded by Cloudflare Email Routing to the owner’s Gmail. Cloudflare and Google process that email to deliver it. Direct emails are handled in the owner’s mailbox; they are not saved as website enquiry files.</p><p>Al uses your details to answer your questions and discuss availability or an inspection. Any further sharing of your personal information can be discussed with you as part of that conversation.</p><p>Website enquiry files remain on the server until the owner removes them. There is no automatic deletion schedule. Email copies remain in the owner’s mailbox until removed there. You can use the <a href="/enquiries/">enquiry form</a> or email us to ask to access, correct or delete information you have submitted; include your enquiry reference if you have it.</p><h2>When your enquiry is received</h2><p>A thank-you message appears only after a form enquiry has been saved. If saving fails, the form keeps your entries so you can retry. Receiving an enquiry does not reserve a room or confirm an inspection time.</p><h2>Website operation</h2><p>Cloudflare carries website traffic, including form submissions, between your browser and our server. Technical request information may be processed in network logs. The application uses your network address temporarily in memory to limit spam; it is not saved with your enquiry. Form enquiry content is not written to application logs.</p><p>The website has no advertising trackers, analytics scripts or external video embeds. Photos and the walkthrough are served directly from this website.</p></section></div>'''.replace('{PUBLIC_EMAIL}',PUBLIC_EMAIL)
page('/privacy/','Privacy & enquiry information | SDA Tarneit','How SDA Tarneit collects, privately stores and uses accommodation enquiries, and how to request access, correction or deletion.',privacy)
walkthrough=f'''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">EXPLORE THE ACTUAL HOME</p><h1>Walk through Social Street.</h1><p>A recorded walkthrough · 2 min 15 sec. Press play when you’re ready.</p></section><video class="walkthrough-video" controls playsinline preload="none" poster="/assets/photo-051-800.webp" src="/assets/tarneit-720p.mp4" aria-label="Recorded walkthrough of the Social Street home"></video><p class="media-disclaimer">The video is a visual walkthrough, not a transcript. Current availability, furnishing and property features are described on the home details page.</p><section class="section-space prose"><h2>A room-by-room overview</h2><p>The video begins outside and shows the entrance and separate overnight assistance room with its ensuite. It continues through participant bedroom one and its ensuite, the shared kitchen, dining and living areas, then participant bedroom two and its ensuite.</p><p>The final indoor views include the laundry and garage. The walkthrough also shows the covered alfresco and rear garden. It does not replace an inspection for checking your access or equipment needs.</p><p>See the <a href="/the-home/#floorplans">illustrative floor plan and confirmed home features</a>, browse the <a href="/#all-photos">real property photos</a>, explore <a href="/living-in-tarneit/">Tarneit and local services</a>, or <a href="/enquiries/">contact Al about the two vacancies</a>.</p><p>For an inspection, <a href="{PHONE_HREF}">call Al on {PHONE}</a> or <a href="{SMS_HREF}">send a text</a>.</p></section>{cta()}</div>'''
page('/walkthrough/','Walk through the Tarneit SDA home | video guide','Watch the 2 minute walkthrough of this Tarneit SDA home. Read a factual room-by-room overview and explore the home, plan and photos.',walkthrough)

